// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

export interface CycleListItemOut {
  cycle_id: number;
  cycle_number: string;
  title: string;
  period_start: string;
  period_end: string;
  due_date: string;
  status: "Planned" | "InReview" | "Closed" | "Cancelled";
  created_at: string;
  closed_at: string | null;
  is_overdue: boolean;
  items_total: number;
  items_reviewed: number;
  open_deficiencies: number;
}

/** The surveyor's report of one cycle, with the MSDS 156-162 ratings. */
export interface ReportOut {
  cycle: ReportCycleOut;
  plan: PlanOut | null;
  reviewers: ReviewerOut[];
  by_stratum: StratumResultOut[];
  by_category: CategoryResultOut[];
  by_criterion: CriterionResultOut[];
  deficiencies: DeficiencyOut[];
  actions: QualityActionOut[];
  msds: MsdsRatingOut[];
}

export interface ReportCycleOut {
  cycle_id: number;
  cycle_number: string;
  title: string;
  period_start: string;
  period_end: string;
  due_date: string;
  status: "Planned" | "InReview" | "Closed" | "Cancelled";
  summary: string | null;
  sampled_at: string | null;
  closed_at: string | null;
  closed_by_name: string | null;
  sample_seed: number | null;
}

/** How the sample is drawn (MSDS 157): Cochran's sample size, proportional allocation, a minimum per stratum. */
export interface PlanOut {
  method: string;
  confidence_level: number;
  z: number;
  margin_pct: number;
  min_per_stratum: number;
  population: number;
  /** Cochran's n for the whole population */
  required_sample: number;
  /** What the strata add up to (at least required_sample, because of the minimum) */
  planned_sample: number;
  includes_open_records: boolean;
  includes_closed_records: boolean;
  strata: StratumOut[];
  /** Only once the sample is drawn */
  drawn_records?: number | null;
  /** Drawn records no panel member may review (they wrote in them) */
  unassigned?: number | null;
}

export interface StratumOut {
  stratum: string;
  department_id: number | null;
  department_name: string | null;
  record_state: "Active" | "Discharged" | "Visit";
  population: number;
  sample: number;
}

export interface ReviewerOut {
  user_id: number;
  display_name: string;
  discipline: "Medical" | "Nursing" | "Pharmacy" | "Laboratory" | "Other";
  is_active: boolean;
  assigned: number;
  reviewed: number;
}

export interface StratumResultOut {
  department_name: string | null;
  record_state: "Active" | "Discharged" | "Visit";
  sampled: number;
  reviewed: number;
  average_score_pct: number | null;
}

export interface CategoryResultOut {
  category: "Timeliness" | "Legibility" | "Completeness";
  yes: number;
  no: number;
  /** Yes / (Yes + No) */
  compliance_pct: number | null;
}

export interface CriterionResultOut {
  code: string;
  title: string;
  category: "Timeliness" | "Legibility" | "Completeness";
  yes: number;
  no: number;
  na: number;
  checked_by_system: number;
  agreed_with_system: number;
}

/** A deficiency found in a record (MSDS 161). */
export interface DeficiencyOut {
  deficiency_id: number;
  cycle_id: number;
  cycle_number: string;
  item_id: number;
  record_type: "Admission" | "OpdVisit";
  record_number: string;
  mrn: string;
  criterion_code: string;
  criterion_title: string;
  category: "Timeliness" | "Legibility" | "Completeness";
  description: string;
  /** Null: the ward's nursing team (nursing supervisors resolve it) */
  responsible_employee_id: number | null;
  responsible_name: string | null;
  status: "Open" | "Corrected" | "Acknowledged" | "Withdrawn";
  resolution_note: string | null;
  resolved_at: string | null;
  resolved_by_name: string | null;
  raised_by: number;
  raised_by_name: string;
  created_at: string;
}

/** A corrective or preventive action of the hospital's register (MSDS IMS 162, CQI 83, 107). */
export interface QualityActionOut {
  action_id: number;
  action_number: string;
  /** What found the need: a medical record review, an incident, a complaint, an infection control audit, a committee meeting, a mock drill, a mock PHC interview, a QA round, a patient's feedback */
  source: "RecordReview" | "Incident" | "Complaint" | "InfectionAudit" | "Meeting" | "Drill" | "MockInterview" | "QaRound" | "PatientFeedback";
  cycle_id: number | null;
  cycle_number: string | null;
  incident_id: number | null;
  incident_number: string | null;
  complaint_id: number | null;
  complaint_number: string | null;
  ipc_audit_id: number | null;
  audit_number: string | null;
  meeting_id: number | null;
  meeting_number: string | null;
  drill_id: number | null;
  drill_number: string | null;
  mock_interview_id: number | null;
  /** The mock PHC interview that found the gap (MIV-...) */
  interview_number: string | null;
  qa_round_id: number | null;
  /** The in-charge's QA round whose finding it addresses (QAR-...) */
  qa_round_number: string | null;
  feedback_id: number | null;
  /** The patient feedback it answers (FB-...) */
  feedback_number: string | null;
  /** The number of the review cycle, the incident, the complaint, the audit or the meeting */
  source_number: string;
  action_type: "Corrective" | "Preventive";
  description: string;
  /** A record review: the checklist item whose deficiencies it addresses */
  criterion_code: string | null;
  department_id: number | null;
  department_name: string | null;
  owner_user_id: number;
  owner_name: string;
  due_date: string;
  status: "Open" | "Done" | "Cancelled";
  /** Done: what was done (the evidence); Cancelled: why it was dropped */
  outcome_note: string | null;
  completed_at: string | null;
  completed_by_name: string | null;
  created_by: number;
  created_by_name: string;
  created_at: string;
  row_version: number;
  is_overdue: boolean;
}

/** How a surveyor would score one MSDS indicator, from the data. */
export interface MsdsRatingOut {
  indicator: number;
  title: string;
  status: "Met" | "PartlyMet" | "NotMet";
  evidence: string;
}

export interface ResolveIn {
  status: "Corrected" | "Acknowledged" | "Withdrawn";
  /** Corrected: what was fixed (e.g. the correction entry) */
  note: string;
}

export interface RecordReviewActionIn {
  action_type: "Corrective" | "Preventive";
  description: string;
  /** Who carries it out; they are notified and close it with the evidence (GET /staff/lookup → user_id; GET /quality/record-review/people, GET /facility/staff) */
  owner_user_id: number;
  due_date: string;
  /** The department (GET /admin/departments) */
  department_id?: number | null;
  /** The checklist item whose deficiencies it addresses */
  criterion_code?: string | null;
}

export interface ActionDoneIn {
  status: "Done" | "Cancelled";
  /** Done: what was done (the evidence); Cancelled: why it was dropped */
  note: string;
  /** Optimistic concurrency: the row_version you loaded */
  expected_version?: number | null;
}

/** A checklist item. auto_check = the system check that pre-answers it (null: the reviewer decides). */
export interface CriterionOut {
  criterion_id: number;
  code: string;
  category: "Timeliness" | "Legibility" | "Completeness";
  applies_to: "Admission" | "OpdVisit" | "Both";
  /** Who fixes a No: the record's Doctor, or the ward's Nursing team */
  responsible: "Doctor" | "Nursing";
  title: string;
  guidance: string | null;
  auto_check: "admission_reason" | "provisional_diagnosis" | "care_plan" | "discharge_summary" | "transfer_record" | "vitals_on_schedule" | "doses_charted" | "general_consent" | "procedure_consent" | "operative_note" | "anaesthesia_record" | "safety_checklist" | "death_certificate" | "autopsy_report" | "chief_complaint" | "visit_diagnosis" | "visit_plan" | "notes_signed" | "notes_timely" | "icd_coded" | "verbal_orders" | "wristband" | "own_medicines" | "critical_results" | "diagnostic_turnaround" | "nutrition_screening" | "nursing_care_plan" | null;
  sort_order: number;
  is_active: boolean;
  row_version: number;
}

export interface CriterionIn {
  code: string;
  category: "Timeliness" | "Legibility" | "Completeness";
  applies_to: "Admission" | "OpdVisit" | "Both";
  responsible?: "Doctor" | "Nursing";
  title: string;
  guidance?: string | null;
  sort_order?: number;
}

export interface CriterionUpdateIn {
  title?: string | null;
  guidance?: string | null;
  sort_order?: number | null;
  is_active?: boolean | null;
  /** row_version you edited (optimistic locking) */
  expected_version?: number | null;
}

export interface DepartmentOut {
  department_id: number;
  code: string;
  name: string;
  is_clinical: boolean;
  is_active: boolean;
  row_version: number;
}

/** An active member of staff a quality record may name (an action's owner, an investigator, a contact person, a committee's member); `can_review`: also on the record review panel. */
export interface PersonOut {
  user_id: number;
  display_name: string;
  designation: string | null;
  department_name: string | null;
  staff_category: "Clinical" | "Nursing" | "Administrative" | "Technical" | "SupportZeroInterface" | "Visiting" | null;
  /** Holds quality.review.perform: may sit on the record review panel */
  can_review: boolean;
  default_discipline: "Medical" | "Nursing" | "Pharmacy" | "Laboratory" | "Other";
}

/** Review cycles (newest period first) — GET /api/v1/quality/record-reviews (who may call: holders of quality.review.manage or quality.review.view). */
export function listCyclesQualityRecordReviews(query?: { status?: "Planned" | "InReview" | "Closed" | "Cancelled" | null; limit?: number }): Promise<CycleListItemOut[]> {
  return api<CycleListItemOut[]>("GET", withQuery(`/quality/record-reviews`, query), undefined);
}

/** The surveyor's report, with the MSDS 156-162 ratings — GET /api/v1/quality/record-reviews/{cycle_id}/report (who may call: holders of quality.review.manage or quality.review.view). */
export function reportQualityRecordReviews(cycle_id: number): Promise<ReportOut> {
  return api<ReportOut>("GET", `/quality/record-reviews/${cycle_id}/report`, undefined);
}

/** The surveyor's report as a PDF — GET /api/v1/quality/record-reviews/{cycle_id}/report/pdf (who may call: holders of quality.review.manage or quality.review.view). */
export function reportPdfQualityRecordReviews(cycle_id: number): Promise<unknown> {
  return api<unknown>("GET", `/quality/record-reviews/${cycle_id}/report/pdf`, undefined);
}

/** Record deficiencies (mine: to fix, or raised by me) — GET /api/v1/quality/record-review-deficiencies (who may call: holders of quality.review.manage or quality.deficiency.resolve or quality.review.perform). */
export function deficiencies(query?: { cycle_id?: number | null; status?: "Open" | "Corrected" | "Acknowledged" | "Withdrawn" | null; mine?: boolean; limit?: number }): Promise<DeficiencyOut[]> {
  return api<DeficiencyOut[]>("GET", withQuery(`/quality/record-review-deficiencies`, query), undefined);
}

/** Resolve a deficiency — POST /api/v1/quality/record-review-deficiencies/{deficiency_id}/resolve (who may call: holders of quality.review.manage or quality.deficiency.resolve or quality.review.perform). */
export function resolve(deficiency_id: number, body: ResolveIn): Promise<DeficiencyOut> {
  return api<DeficiencyOut>("POST", `/quality/record-review-deficiencies/${deficiency_id}/resolve`, body);
}

/** Record a corrective or preventive action — POST /api/v1/quality/record-reviews/{cycle_id}/actions (who may call: holders of quality.review.manage). */
export function addActionQualityRecordReviewsActions(cycle_id: number, body: RecordReviewActionIn): Promise<QualityActionOut> {
  return api<QualityActionOut>("POST", `/quality/record-reviews/${cycle_id}/actions`, body, { idempotent: true });
}

/** The action register (mine: the actions I own) — GET /api/v1/quality/actions (who may call: any logged-in user: the actions they own (mine is forced without quality.action.view or quality.action.manage)). */
export function listActions(query?: { source?: "RecordReview" | "Incident" | "Complaint" | "InfectionAudit" | "Meeting" | "Drill" | "MockInterview" | "QaRound" | "PatientFeedback" | null; status?: "Open" | "Done" | "Cancelled" | null; mine?: boolean; overdue_only?: boolean; department_id?: number | null; limit?: number }): Promise<QualityActionOut[]> {
  return api<QualityActionOut[]>("GET", withQuery(`/quality/actions`, query), undefined);
}

/** Close an action: done with the evidence, or cancelled — POST /api/v1/quality/actions/{action_id}/complete (who may call: the action's owner or quality.action.manage). */
export function completeAction(action_id: number, body: ActionDoneIn): Promise<QualityActionOut> {
  return api<QualityActionOut>("POST", `/quality/actions/${action_id}/complete`, body);
}

/** The review checklist — GET /api/v1/quality/record-review/criteria (who may call: holders of quality.review.manage or quality.review.view or quality.review.perform). */
export function criteria(query?: { active_only?: boolean }): Promise<CriterionOut[]> {
  return api<CriterionOut[]>("GET", withQuery(`/quality/record-review/criteria`, query), undefined);
}

/** Add a checklist item of the hospital's own — POST /api/v1/quality/record-review/criteria (who may call: holders of quality.review.manage). */
export function addCriterion(body: CriterionIn): Promise<CriterionOut> {
  return api<CriterionOut>("POST", `/quality/record-review/criteria`, body, { idempotent: true });
}

/** Reword, reorder or retire a checklist item — PATCH /api/v1/quality/record-review/criteria/{criterion_id} (who may call: holders of quality.review.manage). */
export function updateCriterion(criterion_id: number, body: CriterionUpdateIn): Promise<CriterionOut> {
  return api<CriterionOut>("PATCH", `/quality/record-review/criteria/${criterion_id}`, body);
}

/** Departments — GET /api/v1/admin/departments (who may call: any logged-in user). */
export function departments(): Promise<DepartmentOut[]> {
  return api<DepartmentOut[]>("GET", `/admin/departments`, undefined);
}

/** Every member of staff a quality record may name (and who can review records) — GET /api/v1/quality/record-review/people (who may call: any logged-in user). */
export function people(): Promise<PersonOut[]> {
  return api<PersonOut[]>("GET", `/quality/record-review/people`, undefined);
}
